import { expect, test } from "bun:test";
import { copyFile, mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

// The real source checker must ignore the HTML/JS generated by frontend builds,
// while continuing to check hand-authored frontend sources.
test("AI-writing gate ignores frontend build output but still checks source", async () => {
    const root = await mkdtemp(join(tmpdir(), "gallery-writing-gate-"));
    try {
        await mkdir(join(root, "scripts"));
        await mkdir(join(root, "frontend", "dist"), { recursive: true });
        await mkdir(join(root, "frontend", "src"), { recursive: true });
        await copyFile(
            "scripts/check_ai_writing.ts",
            join(root, "scripts", "check_ai_writing.ts"),
        );
        await writeFile(
            join(root, "frontend", "dist", "actuators.html"),
            "<b>\u2014</b>",
        );
        const check = async () => {
            const proc = Bun.spawn(
                [process.execPath, join(root, "scripts", "check_ai_writing.ts")],
                { stdout: "pipe", stderr: "pipe" },
            );
            const [output, error, exit] = await Promise.all([
                new Response(proc.stdout).text(),
                new Response(proc.stderr).text(),
                proc.exited,
            ]);
            return { output, error, exit };
        };
        const builtOnly = await check();
        expect(builtOnly.exit, builtOnly.output + builtOnly.error).toBe(0);
        await writeFile(
            join(root, "frontend", "src", "authored.ts"),
            "// bad authored prose: \u2014",
        );
        const authored = await check();
        expect(authored.exit).toBe(1);
        expect(authored.output).toContain("frontend/src/authored.ts");
        expect(authored.output).not.toContain("frontend/dist/actuators.html");
    } finally {
        await rm(root, { recursive: true, force: true });
    }
});
